public class Main {
    public static void main(String[] args) {
        // Pattern 1: Right-Angled Number Triangle
        int rows = 4;
        System.out.println("--- Right Triangle Pattern ---");
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= r; c++) {
                System.out.print(c + " ");
            }
            System.out.println();
        }

        // Pattern 2: Reverse a Number via % 10 and / 10
        System.out.println("
--- Digit Reversal ---");
        int original = 1234;
        int reversed = 0;
        int temp = original;

        while (temp > 0) {
            int digit = temp % 10;
            reversed = (reversed * 10) + digit;
            temp /= 10;
        }

        System.out.println("Original: " + original);
        System.out.println("Reversed: " + reversed);
    }
}

