public class Main {
    public static void main(String[] args) {
        int number = 1221;
        int temp = number;
        int rev = 0;
        while (temp > 0) {
            rev = (rev * 10) + (temp % 10);
            temp /= 10;
        }
        System.out.println("Original: " + number);
        System.out.println("Reversed: " + rev);
        if (rev == number) {
            System.out.println(number + " is a Palindrome!");
        } else {
            System.out.println(number + " is Not a Palindrome");
        }
    }
}

