        }
        System.out.println("Sum of Digits: " + sum);
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 17;
        boolean isPrime = true;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            System.out.println(n + " is Prime");
        } else {
            System.out.println(n + " is Not Prime");
        }
    }
}

public class Main {
