            for (int c = 1; c <= r; c++) {
                if (c == r) {
                    System.out.print(val);
                } else {
                    System.out.print(val + " ");
                }
                val++;
            }
            System.out.println();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int num = 153;
        int temp = num;
        int sum = 0;
        while (temp > 0) {
            int d = temp % 10;
            sum += d * d * d;
            temp /= 10;
        }
        if (sum == num) {
            System.out.println(num + " is an Armstrong number");
        } else {
            System.out.println(num + " is Not an Armstrong number");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 72485;
        int evens = 0, odds = 0;
        while (n > 0) {
            int d = n % 10;
            if (d % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
            n /= 10;
        }
        System.out.println("Even Digits: " + evens);
        System.out.println("Odd Digits: " + odds);
    }
}

public class Main {
    public static void main(String[] args) {
        int rows = 3;
        for (int r = 1; r <= rows; r++) {
            for (int s = 1; s <= rows - r; s++) {
                System.out.print(" ");
            }
            for (int st = 1; st <= 2 * r - 1; st++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }
}
